// Port of service/dfma/tools.py: generic tools (spec "Tools"). S2 ports the drills, generated by rule from
// config/tools.toml; S3 the end mills, for the plan.
import { toolsConfig } from "./settings";
import { METRIC, MM_PER_IN, pyFixed, pyG, round } from "./units";

export interface Drill { diameter_mm: number; label: string; metric: boolean }

function steps(start: number, stop: number, step: number): number[] {
  const n = round((stop - start) / step, 0);
  return Array.from({ length: n + 1 }, (_, i) => round(start + i * step, 6));
}

type Ranges = Record<string, number>[];
let cached: Map<string, Drill[]> | null = null;

/** The drill set for a part: 1/64 in drills for inch, other and no-unit files; for metric files (D-020), metric
 *  drills plus the 1/64 in drills, because inch-designed parts are often exported in mm (D-013). */
export function drills(unitsInFile: string): Drill[] {
  cached ??= new Map();
  const metricFile = METRIC.includes(unitsInFile);
  const key = metricFile ? "metric" : "inch";
  if (!cached.has(key)) {
    const cfg = toolsConfig().drills as { inch: Ranges; mm: Ranges };
    const inch = cfg.inch.flatMap((r) => steps(r.from_in, r.to_in, r.step_in))
      .map((d) => ({ diameter_mm: d * MM_PER_IN, label: `${pyFixed(d, 4)} in`, metric: false }));
    const metric = cfg.mm.flatMap((r) => steps(r.from_mm, r.to_mm, r.step_mm))
      .map((d) => ({ diameter_mm: d, label: `${pyG(d)} mm`, metric: true }));
    cached.set(key, metricFile ? [...metric, ...inch] : inch);
  }
  return cached.get(key)!;
}

export function matchToleranceMm(): number {
  return ((toolsConfig().drills as Record<string, number>).match_tolerance_in) * MM_PER_IN;
}

/** The closest drill; a tie (to 1e-6 mm) goes to the smaller drill, and Python's min keeps the first after that. */
export function nearestDrill(diameterMm: number, unitsInFile: string): Drill {
  let best: Drill | null = null;
  let bestKey: [number, number] = [Infinity, Infinity];
  for (const d of drills(unitsInFile)) {
    const key: [number, number] = [round(Math.abs(d.diameter_mm - diameterMm), 6), d.diameter_mm];
    if (key[0] < bestKey[0] || (key[0] === bestKey[0] && key[1] < bestKey[1])) [best, bestKey] = [d, key];
  }
  return best!;
}

export function drillRangeMm(unitsInFile: string): [number, number] {
  const sizes = drills(unitsInFile).map((d) => d.diameter_mm);
  return [Math.min(...sizes), Math.max(...sizes)];
}

export const PICK_TOL_MM = 0.001; // a corner radius equal to a tool's radius fits (spec S3 "Settled at build")

/** The inch end-mill list, in mm, smallest first. Every file uses it (no metric end mills yet). */
export function endMillsMm(): number[] {
  return ((toolsConfig().end_mills as { inch: number[] }).inch).map((d) => d * MM_PER_IN).sort((a, b) => a - b);
}

/** The largest end mill (diameter, mm) whose radius is at most the corner radius and whose diameter is at most the
 *  width; when none fits, the smallest, with undersized true. */
export function pickEndMill(minCornerRadius: number, narrowestWidth: number): [number, boolean] {
  const mills = endMillsMm();
  const fits = mills.filter((d) => d / 2 <= minCornerRadius + PICK_TOL_MM && d <= narrowestWidth + PICK_TOL_MM);
  return fits.length ? [fits[fits.length - 1], false] : [mills[0], true];
}
